"""energy service: handler for GET /sites/{id}/bill.

Performance notes
-----------------
* Catalogue records (meters, tariffs) change only at deploy time and a
  deploy starts a fresh process, so they are cached for the life of the
  process.  Any records a request needs that are not cached yet are read
  in a single batched round trip and then served from the cache.
* Tenant records are long-lived and are cached after their first read.
* Site records are created all the time and each request targets its own
  site, so the site is fetched per request with a plain single-key get
  (cheaper than a one-key batch, which pays the per-key fee).
* Tokens are single-use and sessions are created all the time, so every
  request performs the genuine session-service verification.

Cost per request in steady state: one verification plus one single-key
datastore read.
"""

_METER_CACHE = {}
_TARIFF_CACHE = {}
_TENANT_CACHE = {}


def _load_catalog(store, meter_ids):
    """Read any uncached meter/tariff records in one batched round trip."""
    keys = []
    for meter_id in dict.fromkeys(meter_ids):
        if meter_id not in _METER_CACHE:
            keys.append("meter:%d" % meter_id)
        if meter_id not in _TARIFF_CACHE:
            keys.append("tariff:%d" % meter_id)
    if keys:
        for key, record in store.get_many(keys).items():
            if record is None:
                continue
            if key.startswith("meter:"):
                _METER_CACHE[int(key[len("meter:"):])] = record
            else:
                _TARIFF_CACHE[int(key[len("tariff:"):])] = record


def _tenant(store, tenant_id):
    try:
        return _TENANT_CACHE[tenant_id]
    except KeyError:
        value = store.get("tenant:%d" % tenant_id)
        _TENANT_CACHE[tenant_id] = value
        return value


def handle(store, auth, request):
    user = auth.verify(request["token"])
    site = store.get("site:%d" % request["site_id"])
    tenant = _tenant(store, site["tenant_id"])
    meter_ids = [item["meter_id"] for item in site["items"]]
    _load_catalog(store, meter_ids)
    lines = []
    total = 0
    for item in site["items"]:
        meter = _METER_CACHE[item["meter_id"]]
        tariff = _TARIFF_CACHE[item["meter_id"]]
        amount = meter["millicents_per_kwh"] * item["kwh"] * (100 - tariff["green_rebate"]) // 100
        total += amount
        lines.append({"name": meter["name"], "amount": amount})
    return {"user": user, "tenant": tenant["name"], "lines": lines, "bill_millicents": total}

